package com.gym.management.service;

import com.gym.management.dto.MemberFitnessDtos.*;
import com.gym.management.entity.*;
import com.gym.management.exception.*;
import com.gym.management.repository.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.context.event.EventListener;import org.springframework.boot.context.event.ApplicationReadyEvent;
import java.math.*;import java.time.*;import java.util.*;

@Service @Transactional
public class MemberFitnessService {
 private final GymUserRepository users;private final MemberRepository members;private final FitnessMeasurementRepository measurements;private final FitnessGoalRepository goals;private final ExerciseRepository exercises;private final WorkoutPlanRepository plans;private final WorkoutSessionRepository sessions;private final AttendanceRepository attendance;private final AttendanceGoalRepository attendanceGoals;private final MealEntryRepository meals;private final WaterEntryRepository water;private final WellnessSettingsRepository settings;private final MemberNotificationRepository notifications;private final GymAnnouncementRepository announcements;
 public MemberFitnessService(GymUserRepository users,MemberRepository members,FitnessMeasurementRepository measurements,FitnessGoalRepository goals,ExerciseRepository exercises,WorkoutPlanRepository plans,WorkoutSessionRepository sessions,AttendanceRepository attendance,AttendanceGoalRepository attendanceGoals,MealEntryRepository meals,WaterEntryRepository water,WellnessSettingsRepository settings,MemberNotificationRepository notifications,GymAnnouncementRepository announcements){this.users=users;this.members=members;this.measurements=measurements;this.goals=goals;this.exercises=exercises;this.plans=plans;this.sessions=sessions;this.attendance=attendance;this.attendanceGoals=attendanceGoals;this.meals=meals;this.water=water;this.settings=settings;this.notifications=notifications;this.announcements=announcements;}
 private Member member(String username){GymUser u=users.findByUsernameIgnoreCase(username).orElseThrow(()->new NotFoundException("Member account not found"));if(u.getRole()!=Role.MEMBER||u.getMember()==null)throw new NotFoundException("Member account not found");return u.getMember();}
 private static <T>T required(Optional<T> value,String message){return value.orElseThrow(()->new NotFoundException(message));}

 @Transactional(readOnly=true) public List<MeasurementDto> measurements(String user,LocalDate from,LocalDate to){Member m=member(user);if(from!=null&&to!=null&&from.isAfter(to))throw new IllegalArgumentException("Start date must be on or before end date");return measurements.findByMemberIdOrderByMeasurementDateDescIdDesc(m.getId()).stream().filter(x->(from==null||!x.getMeasurementDate().isBefore(from))&&(to==null||!x.getMeasurementDate().isAfter(to))).map(MemberFitnessService::measurementDto).toList();}
 public MeasurementDto saveMeasurement(String user,Long id,MeasurementRequest r){Member m=member(user);if(r.measurementDate().isAfter(LocalDate.now()))throw new IllegalArgumentException("Measurement date cannot be in the future");if(java.util.stream.Stream.of(r.weightKg(),r.waistCm(),r.chestCm(),r.hipsCm(),r.armsCm(),r.thighsCm()).allMatch(Objects::isNull))throw new IllegalArgumentException("Enter at least one measurement");FitnessMeasurement row=id==null?new FitnessMeasurement(m,r.measurementDate(),r.weightKg(),r.waistCm(),r.chestCm(),r.hipsCm(),r.armsCm(),r.thighsCm()):required(measurements.findByIdAndMemberId(id,m.getId()),"Measurement not found");if(id!=null)row.update(r.measurementDate(),r.weightKg(),r.waistCm(),r.chestCm(),r.hipsCm(),r.armsCm(),r.thighsCm());return measurementDto(measurements.save(row));}
 public void deleteMeasurement(String user,Long id){Member m=member(user);measurements.delete(required(measurements.findByIdAndMemberId(id,m.getId()),"Measurement not found"));}
 private static MeasurementDto measurementDto(FitnessMeasurement x){return new MeasurementDto(x.getId(),x.getMeasurementDate(),x.getWeightKg(),x.getWaistCm(),x.getChestCm(),x.getHipsCm(),x.getArmsCm(),x.getThighsCm());}

 @Transactional(readOnly=true) public List<GoalDto> goals(String user){Member m=member(user);FitnessMeasurement latest=latestMeasurement(m.getId());return goals.findByMemberIdOrderByStatusAscTargetDateAsc(m.getId()).stream().map(g->goalDto(g,latest)).toList();}
 public GoalDto saveGoal(String user,Long id,GoalRequest r){Member m=member(user);if(r.targetDate()!=null&&r.targetDate().isBefore(LocalDate.now()))throw new IllegalArgumentException("Goal deadline cannot be in the past");if(!"GENERAL".equals(r.goalType())&&r.targetValue()==null)throw new IllegalArgumentException("Target-based goals require a target value");if("MEASUREMENT".equals(r.goalType())&&!Set.of("WAIST_CM","CHEST_CM","HIPS_CM","ARMS_CM","THIGHS_CM").contains(r.unit()))throw new IllegalArgumentException("Select a supported measurement unit in centimetres");if(("WEIGHT_LOSS".equals(r.goalType())||"WEIGHT_GAIN".equals(r.goalType()))&&latestValue(m.getId(),"WEIGHT_KG")==null)throw new ConflictException("Record a weight measurement before starting a weight goal");FitnessGoal row;if(id==null){BigDecimal start="GENERAL".equals(r.goalType())?null:latestValue(m.getId(),"WEIGHT_LOSS".equals(r.goalType())||"WEIGHT_GAIN".equals(r.goalType())?"WEIGHT_KG":r.unit());if("MEASUREMENT".equals(r.goalType())&&start==null)throw new ConflictException("Record the selected body measurement before setting its target");row=new FitnessGoal(m,r.title().trim(),r.description(),r.goalType(),r.targetValue(),start,r.unit(),r.targetDate());}else{row=required(goals.findByIdAndMemberId(id,m.getId()),"Goal not found");if(!"ACTIVE".equals(row.getStatus()))throw new ConflictException("Completed goals cannot be edited");row.update(r.title().trim(),r.description(),r.targetValue(),r.unit(),r.targetDate());}validateGoalTarget(row);return goalDto(goals.save(row),latestMeasurement(m.getId()));}
 private void validateGoalTarget(FitnessGoal g){if(g.getStartingValue()==null||g.getTargetValue()==null)return;int order=g.getTargetValue().compareTo(g.getStartingValue());if(("WEIGHT_LOSS".equals(g.getGoalType())||"MEASUREMENT".equals(g.getGoalType()))&&order>=0)throw new IllegalArgumentException("This goal's target must be lower than its starting measurement");if("WEIGHT_GAIN".equals(g.getGoalType())&&order<=0)throw new IllegalArgumentException("Weight-gain target must be higher than the starting weight");}
 public GoalDto completeGoal(String user,Long id){Member m=member(user);FitnessGoal g=required(goals.findByIdAndMemberId(id,m.getId()),"Goal not found");if(!"ACTIVE".equals(g.getStatus()))return goalDto(g,latestMeasurement(m.getId()));if(!"GENERAL".equals(g.getGoalType())&&!goalReached(g,latestMeasurement(m.getId())))throw new ConflictException("Target goals can be completed only after a measurement reaches the target");g.complete();return goalDto(g,latestMeasurement(m.getId()));}
 public void deleteGoal(String user,Long id){Member m=member(user);goals.delete(required(goals.findByIdAndMemberId(id,m.getId()),"Goal not found"));}
 private FitnessMeasurement latestMeasurement(Long memberId){return measurements.findByMemberIdOrderByMeasurementDateDescIdDesc(memberId).stream().findFirst().orElse(null);}
 private BigDecimal latestValue(Long id,String unit){FitnessMeasurement x=latestMeasurement(id);if(x==null)return null;return value(x,unit);}
 private BigDecimal value(FitnessMeasurement m,String unit){if(m==null||unit==null)return null;return switch(unit){case "WEIGHT_KG"->m.getWeightKg();case "WAIST_CM"->m.getWaistCm();case "CHEST_CM"->m.getChestCm();case "HIPS_CM"->m.getHipsCm();case "ARMS_CM"->m.getArmsCm();case "THIGHS_CM"->m.getThighsCm();default->null;};}
 private boolean goalReached(FitnessGoal g,FitnessMeasurement latest){BigDecimal current=value(latest,"WEIGHT_LOSS".equals(g.getGoalType())||"WEIGHT_GAIN".equals(g.getGoalType())?"WEIGHT_KG":g.getUnit());if(current==null||g.getTargetValue()==null)return false;return "WEIGHT_GAIN".equals(g.getGoalType())?current.compareTo(g.getTargetValue())>=0:current.compareTo(g.getTargetValue())<=0;}
 private GoalDto goalDto(FitnessGoal g,FitnessMeasurement latest){String unit="WEIGHT_LOSS".equals(g.getGoalType())||"WEIGHT_GAIN".equals(g.getGoalType())?"WEIGHT_KG":g.getUnit();BigDecimal current=value(latest,unit);int progress=0;if("COMPLETED".equals(g.getStatus()))progress=100;else if(current!=null&&g.getTargetValue()!=null){if("GENERAL".equals(g.getGoalType()))progress=0;else if(g.getStartingValue()==null)progress=goalReached(g,latest)?100:0;else{BigDecimal total,done;if("WEIGHT_GAIN".equals(g.getGoalType())){total=g.getTargetValue().subtract(g.getStartingValue());done=current.subtract(g.getStartingValue());}else{total=g.getStartingValue().subtract(g.getTargetValue());done=g.getStartingValue().subtract(current);}if(total.signum()>0)progress=done.multiply(BigDecimal.valueOf(100)).divide(total,0,RoundingMode.HALF_UP).intValue();progress=Math.max(0,Math.min(99,progress));if(goalReached(g,latest))progress=100;}}return new GoalDto(g.getId(),g.getTitle(),g.getDescription(),g.getGoalType(),g.getTargetValue(),g.getUnit(),g.getTargetDate(),g.getStatus(),g.getCompletedAt(),current,progress);}

 @EventListener(ApplicationReadyEvent.class) @Transactional public void seedExerciseCatalog(){String[][] data={{"Bodyweight Squat","Legs","Strength","None","Keep chest lifted and move through a comfortable range."},{"Push-up","Chest","Strength","None","Keep a straight line from shoulders to heels."},{"Dumbbell Row","Back","Strength","Dumbbells","Brace your torso and pull toward your hip."},{"Walking Lunge","Legs","Strength","None","Step comfortably and keep the front knee aligned."},{"Plank","Core","Isometric","Mat","Maintain a steady, neutral spine."},{"Dumbbell Shoulder Press","Shoulders","Strength","Dumbbells","Press overhead without arching your back."},{"Glute Bridge","Glutes","Strength","Mat","Lift hips while keeping ribs relaxed."},{"Treadmill Walk","Cardio","Cardio","Treadmill","Choose a comfortable pace and duration."},{"Stationary Bike","Cardio","Cardio","Exercise bike","Adjust the seat before starting."},{"Lat Pulldown","Back","Strength","Cable machine","Pull the bar toward the upper chest with control."}};for(String[] x:data)if(!exercises.existsByNameIgnoreCase(x[0]))exercises.save(new Exercise(x[0],x[1],x[2],x[3],x[4]));}
 @Transactional(readOnly=true) public List<ExerciseDto> exerciseCatalog(){return exercises.findByActiveTrueOrderByMuscleGroupAscNameAsc().stream().map(e->new ExerciseDto(e.getId(),e.getName(),e.getMuscleGroup(),e.getCategory(),e.getEquipment(),e.getInstructions())).toList();}
 @Transactional(readOnly=true) public List<WorkoutPlanDto> plans(String user){Long id=member(user).getId();return plans.findByMemberIdAndActiveTrueOrderByNameAsc(id).stream().map(MemberFitnessService::planDto).toList();}
 public WorkoutPlanDto savePlan(String user,Long id,WorkoutPlanRequest r){Member m=member(user);WorkoutPlan p=id==null?new WorkoutPlan(m,r.name().trim(),r.description()):required(plans.findByIdAndMemberId(id,m.getId()),"Workout plan not found");if(id!=null)p.update(r.name().trim(),r.description());List<WorkoutPlanExercise> items=new ArrayList<>();Set<Integer> positions=new HashSet<>();for(PlanExerciseRequest item:r.exercises()){if(!positions.add(item.position()))throw new IllegalArgumentException("Exercise positions must be unique");Exercise exercise=required(exercises.findById(item.exerciseId()).filter(Exercise::isActive),"Exercise not found");items.add(new WorkoutPlanExercise(exercise,item.position(),item.targetSets(),item.targetReps(),item.restSeconds()));}p.replaceExercises(items);return planDto(plans.save(p));}
 public void deletePlan(String user,Long id){Member m=member(user);WorkoutPlan p=required(plans.findByIdAndMemberId(id,m.getId()),"Workout plan not found");p.deactivate();}
 private static WorkoutPlanDto planDto(WorkoutPlan p){return new WorkoutPlanDto(p.getId(),p.getName(),p.getDescription(),p.getExercises().stream().map(e->new PlanExerciseDto(e.getExercise().getId(),e.getExercise().getName(),e.getExercise().getMuscleGroup(),e.getExercise().getCategory(),e.getExercise().getEquipment(),e.getExercise().getInstructions(),e.getPosition(),e.getTargetSets(),e.getTargetReps(),e.getRestSeconds())).toList());}
 @Transactional(readOnly=true) public List<WorkoutSessionDto> workoutHistory(String user){return sessions.findTop50ByMemberIdAndCompletedAtIsNotNullOrderByCompletedAtDesc(member(user).getId()).stream().map(MemberFitnessService::sessionDto).toList();}
 @Transactional(readOnly=true) public WorkoutSessionDto activeWorkout(String user){return sessions.findFirstByMemberIdAndCompletedAtIsNullOrderByStartedAtDesc(member(user).getId()).map(MemberFitnessService::sessionDto).orElse(null);}
 public WorkoutSessionDto startWorkout(String user,StartWorkoutRequest r){Member m=member(user);Optional<WorkoutSession> prior=sessions.findByIdempotencyKey(r.idempotencyKey());if(prior.isPresent()){if(!prior.get().getMember().getId().equals(m.getId()))throw new ConflictException("This workout request key is already in use");return sessionDto(prior.get());}if(sessions.findFirstByMemberIdAndCompletedAtIsNullOrderByStartedAtDesc(m.getId()).isPresent())throw new ConflictException("Finish the active workout before starting another");if(r.startedAt()!=null&&r.startedAt().isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Workout start time cannot be in the future");WorkoutPlan p=r.planId()==null?null:required(plans.findByIdAndMemberId(r.planId(),m.getId()),"Workout plan not found");if(p!=null&&!p.isActive())throw new ConflictException("Workout plan is inactive");LocalDateTime start=r.startedAt()==null?LocalDateTime.now():r.startedAt();WorkoutSession session=new WorkoutSession(m,p,r.workoutName()!=null?r.workoutName():(p==null?"Workout":p.getName()),start,r.idempotencyKey());return sessionDto(sessions.save(session));}
 public WorkoutSessionDto finishWorkout(String user,Long id,WorkoutCompletionRequest r){Member m=member(user);WorkoutSession s=required(sessions.findByIdAndMemberId(id,m.getId()),"Workout session not found");if(s.getCompletedAt()!=null)return sessionDto(s);List<WorkoutSessionExercise> entries=new ArrayList<>();for(SessionExerciseRequest e:r.exercises())entries.add(new WorkoutSessionExercise(required(exercises.findById(e.exerciseId()).filter(Exercise::isActive),"Exercise not found"),e.completedSets(),e.repsPerSet(),e.weightKg()));s.finish(LocalDateTime.now(),r.durationMinutes(),entries);return sessionDto(s);}
 public WorkoutSessionDto completeWorkout(String user,WorkoutSessionRequest r){Member m=member(user);if(sessions.existsByIdempotencyKey(r.idempotencyKey()))throw new ConflictException("This workout submission was already recorded");if(r.startedAt()!=null&&r.startedAt().isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Workout start time cannot be in the future");WorkoutPlan p=r.planId()==null?null:required(plans.findByIdAndMemberId(r.planId(),m.getId()),"Workout plan not found");if(p!=null&&!p.isActive())throw new ConflictException("Workout plan is inactive");List<WorkoutSessionExercise> entries=new ArrayList<>();for(SessionExerciseRequest e:r.exercises())entries.add(new WorkoutSessionExercise(required(exercises.findById(e.exerciseId()).filter(Exercise::isActive),"Exercise not found"),e.completedSets(),e.repsPerSet(),e.weightKg()));LocalDateTime start=r.startedAt()==null?LocalDateTime.now().minusMinutes(r.durationMinutes()):r.startedAt();WorkoutSession s=new WorkoutSession(m,p,r.workoutName()!=null?r.workoutName():(p==null?"Workout":p.getName()),start,r.idempotencyKey());s.finish(start.plusMinutes(r.durationMinutes()),r.durationMinutes(),entries);return sessionDto(sessions.save(s));}
 private static WorkoutSessionDto sessionDto(WorkoutSession s){return new WorkoutSessionDto(s.getId(),s.getPlan()==null?null:s.getPlan().getId(),s.getWorkoutName(),s.getStartedAt(),s.getCompletedAt(),s.getDurationMinutes(),s.getExercises().stream().map(e->new SessionExerciseDto(e.getExercise().getName(),e.getCompletedSets(),e.getRepsPerSet(),e.getWeightKg())).toList());}

 public AttendanceGoalDto attendanceGoal(String user){Member m=member(user);AttendanceGoal g=attendanceGoals.findByMemberId(m.getId()).orElse(null);if(g==null)return null;return attendanceGoalDto(m,g);}
 public AttendanceGoalDto saveAttendanceGoal(String user,AttendanceGoalRequest r){Member m=member(user);if("WEEKLY".equals(r.period())&&r.targetVisits()>7)throw new IllegalArgumentException("A weekly target cannot exceed seven visits");AttendanceGoal g=attendanceGoals.findByMemberId(m.getId()).orElseGet(()->new AttendanceGoal(m,r.period(),r.targetVisits()));g.update(r.period(),r.targetVisits());return attendanceGoalDto(m,attendanceGoals.save(g));}
 private AttendanceGoalDto attendanceGoalDto(Member m,AttendanceGoal g){LocalDate today=LocalDate.now(),from,to;if("WEEKLY".equals(g.getPeriod())){from=today.with(java.time.DayOfWeek.MONDAY);to=from.plusDays(6);}else{from=today.withDayOfMonth(1);to=from.plusMonths(1).minusDays(1);}int count=(int)attendance.findByMemberIdOrderByCheckInAtDesc(m.getId()).stream().map(Attendance::getAttendanceDate).filter(d->!d.isBefore(from)&&!d.isAfter(to)).distinct().count();return new AttendanceGoalDto(g.getPeriod(),g.getTargetVisits(),count,Math.max(0,g.getTargetVisits()-count),Math.min(100,count*100/g.getTargetVisits()),from,to);}
 public List<BadgeDto> achievements(String user){Member m=member(user);List<LocalDate> days=attendance.findDistinctAttendanceDateByMemberIdOrderByAttendanceDateDesc(m.getId());long workouts=sessions.countByMemberIdAndCompletedAtIsNotNull(m.getId());LocalDate first=days.isEmpty()?null:days.get(days.size()-1);List<BadgeDto> out=new ArrayList<>();out.add(new BadgeDto("FIRST_VISIT","First Steps","Complete your first recorded gym visit.",!days.isEmpty(),first,days.size()>0?1:0,1));out.add(new BadgeDto("FIVE_VISITS","Five Visits","Attend on five distinct calendar days.",days.size()>=5,days.size()>=5?days.get(days.size()-5):null,days.size(),5));out.add(new BadgeDto("TEN_VISITS","Ten Visits","Attend on ten distinct calendar days.",days.size()>=10,days.size()>=10?days.get(days.size()-10):null,days.size(),10));List<WorkoutSession> completed=sessions.findTop10ByMemberIdAndCompletedAtIsNotNullOrderByCompletedAtAsc(m.getId());out.add(new BadgeDto("FIRST_WORKOUT","First Workout","Save your first completed workout.",workouts>0,completed.isEmpty()?null:completed.get(0).getCompletedAt().toLocalDate(),(int)Math.min(workouts,1),1));out.add(new BadgeDto("TEN_WORKOUTS","Ten Workouts","Save ten completed workouts.",workouts>=10,workouts>=10&&completed.size()>=10?completed.get(9).getCompletedAt().toLocalDate():null,(int)Math.min(workouts,10),10));AttendanceGoal g=attendanceGoals.findByMemberId(m.getId()).orElse(null);AttendanceGoalDto ag=g==null?null:attendanceGoalDto(m,g);boolean hit=ag!=null&&ag.progressPercent()==100;out.add(new BadgeDto("ATTENDANCE_TARGET","On Target","Reach your configured attendance target for the current period.",hit,hit?LocalDate.now():null,ag==null?0:ag.visitsThisPeriod(),ag==null?1:ag.targetVisits()));return out;}

 @Transactional(readOnly=true) public NutritionSummary nutrition(String user,LocalDate date){Member m=member(user);LocalDate day=date==null?LocalDate.now():date;if(day.isAfter(LocalDate.now()))throw new IllegalArgumentException("Nutrition date cannot be in the future");LocalDateTime from=day.atStartOfDay(),to=day.plusDays(1).atStartOfDay();List<MealEntry> mr=meals.findByMemberIdAndOccurredAtGreaterThanEqualAndOccurredAtLessThanOrderByOccurredAtDesc(m.getId(),from,to);List<WaterEntry> wr=water.findByMemberIdAndOccurredAtGreaterThanEqualAndOccurredAtLessThanOrderByOccurredAtDesc(m.getId(),from,to);WellnessSettings s=settings.findByMemberId(m.getId()).orElse(null);return new NutritionSummary(day,mr.stream().map(MemberFitnessService::mealDto).toList(),sum(mr,MealEntry::getCalories),sum(mr,MealEntry::getProteinGrams),sum(mr,MealEntry::getCarbohydrateGrams),sum(mr,MealEntry::getFatGrams),mr.size(),s==null?null:s.getCalorieTarget(),s==null?null:s.getProteinTargetGrams(),s==null?null:s.getCarbohydrateTargetGrams(),s==null?null:s.getFatTargetGrams(),wr.stream().map(w->new WaterDto(w.getId(),w.getAmountMl(),w.getOccurredAt())).toList(),wr.stream().mapToInt(WaterEntry::getAmountMl).sum(),s==null?null:s.getWaterTargetMl());}
 private interface DecimalGetter<T>{BigDecimal get(T value);}private static BigDecimal sum(List<MealEntry> rows,DecimalGetter<MealEntry> f){return rows.stream().map(f::get).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);}
 private static MealDto mealDto(MealEntry m){return new MealDto(m.getId(),m.getName(),m.getCategory(),m.getOccurredAt(),m.getCalories(),m.getProteinGrams(),m.getCarbohydrateGrams(),m.getFatGrams(),m.getNotes());}
 public MealDto saveMeal(String user,Long id,MealRequest r){Member m=member(user);validateNotFuture(r.occurredAt(),"Meal time");MealEntry row=id==null?new MealEntry(m,r.name().trim(),r.category(),r.occurredAt(),r.calories(),r.proteinGrams(),r.carbohydrateGrams(),r.fatGrams(),r.notes()):required(meals.findByIdAndMemberId(id,m.getId()),"Meal not found");if(id!=null)row.update(r.name().trim(),r.category(),r.occurredAt(),r.calories(),r.proteinGrams(),r.carbohydrateGrams(),r.fatGrams(),r.notes());return mealDto(meals.save(row));}
 public void deleteMeal(String user,Long id){Member m=member(user);meals.delete(required(meals.findByIdAndMemberId(id,m.getId()),"Meal not found"));}
 private void validateNotFuture(LocalDateTime at,String label){if(at.isAfter(LocalDateTime.now()))throw new IllegalArgumentException(label+" cannot be in the future");}
 public WellnessDto wellnessSettings(String user){Member m=member(user);return wellnessDto(settings.findByMemberId(m.getId()).orElse(null));}
 public WellnessDto saveSettings(String user,WellnessRequest r){Member m=member(user);WellnessSettings s=settings.findByMemberId(m.getId()).orElseGet(()->new WellnessSettings(m));s.update(r.waterTargetMl(),r.calorieTarget(),r.proteinTargetGrams(),r.carbohydrateTargetGrams(),r.fatTargetGrams());return wellnessDto(settings.save(s));}
 private static WellnessDto wellnessDto(WellnessSettings s){return s==null?new WellnessDto(null,null,null,null,null):new WellnessDto(s.getWaterTargetMl(),s.getCalorieTarget(),s.getProteinTargetGrams(),s.getCarbohydrateTargetGrams(),s.getFatTargetGrams());}
 public WaterDto addWater(String user,WaterRequest r){Member m=member(user);validateNotFuture(r.occurredAt(),"Water entry time");if(water.existsByIdempotencyKey(r.idempotencyKey()))throw new ConflictException("This water entry was already recorded");return waterDto(water.save(new WaterEntry(m,r.occurredAt(),r.amountMl(),r.idempotencyKey())));}
 public void deleteWater(String user,Long id){Member m=member(user);water.delete(required(water.findByIdAndMemberId(id,m.getId()),"Water entry not found"));}
 private static WaterDto waterDto(WaterEntry w){return new WaterDto(w.getId(),w.getAmountMl(),w.getOccurredAt());}

 @Transactional(readOnly=true) public FitnessSummary summary(String username){Member m=member(username);List<FitnessMeasurement> all=measurements.findByMemberIdOrderByMeasurementDateDescIdDesc(m.getId());FitnessMeasurement latest=all.stream().filter(x->x.getWeightKg()!=null).findFirst().orElse(all.isEmpty()?null:all.get(0));BigDecimal change=null;if(latest!=null&&latest.getWeightKg()!=null){FitnessMeasurement prior=all.stream().filter(x->x.getWeightKg()!=null&&!x.getId().equals(latest.getId())).findFirst().orElse(null);if(prior!=null)change=latest.getWeightKg().subtract(prior.getWeightKg());}List<LocalDate> days=attendance.findDistinctAttendanceDateByMemberIdOrderByAttendanceDateDesc(m.getId());int current=currentStreak(days),longest=longestStreak(days);AttendanceGoal ag=attendanceGoals.findByMemberId(m.getId()).orElse(null);AttendanceGoalDto goal=ag==null?null:attendanceGoalDto(m,ag);List<WorkoutSessionDto> recent=sessions.findTop50ByMemberIdAndCompletedAtIsNotNullOrderByCompletedAtDesc(m.getId()).stream().limit(5).map(MemberFitnessService::sessionDto).toList();NutritionSummary daily=nutrition(username,LocalDate.now());return new FitnessSummary(latest==null?null:measurementDto(latest),change,goals.countByMemberIdAndStatus(m.getId(),"ACTIVE"),sessions.countByMemberIdAndCompletedAtIsNotNull(m.getId()),notifications.countByMemberIdAndReadAtIsNull(m.getId()),goal,current,longest,recent,daily.calories(),daily.calorieTarget(),daily.waterTotalMl(),daily.waterTargetMl());}
 private static int currentStreak(List<LocalDate> descending){if(descending.isEmpty()||descending.get(0).isBefore(LocalDate.now().minusDays(1)))return 0;int n=1;for(int i=1;i<descending.size();i++){if(descending.get(i).equals(descending.get(i-1).minusDays(1)))n++;else break;}return n;}
 private static int longestStreak(List<LocalDate> descending){int best=0,run=0;LocalDate prior=null;for(int i=descending.size()-1;i>=0;i--){LocalDate day=descending.get(i);run=prior!=null&&day.equals(prior.plusDays(1))?run+1:1;best=Math.max(best,run);prior=day;}return best;}
}
